#include <cmath>

double exponential_random(double lambda, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    // Update the seed using LCG
    seed = (a * seed + c) % m;

    // Generate uniform random number in (0, 1)
    double U = static_cast<double>(seed) / m;

    // Handle edge cases
    if (lambda <= 0.0) {
        return 0.0; // or throw an error
    }
    if (U == 0.0) {
        U = 1.0 / m; // Avoid log(0)
    }

    // Inverse transform method
    return -std::log(U) / lambda;
}

#include <cmath>

double exponential_random(double lambda, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    // Update the seed using LCG
    seed = (a * seed + c) % m;

    // Generate uniform random number in (0, 1)
    double U = static_cast<double>(seed) / m;

    // Ensure U is in (0, 1)
    if (U == 0.0) {
        U = std::numeric_limits<double>::min(); // Smallest positive double
    }

    // Handle invalid lambda
    if (lambda <= 0.0) {
        return 0.0; // or throw an exception
    }

    // Inverse transform method
    return -std::log(U) / lambda;
}

#include <cmath>

double exponential_random(double lambda, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    // Update the seed using LCG
    seed = (a * seed + c) % m;

    // Generate uniform random number in (0, 1)
    double U = static_cast<double>(seed) / m;

    // Ensure U is in (0, 1)
    if (U == 0.0) {
        U = 1.0 / (m + 1); // Smallest positive value
    }

    // Handle invalid lambda
    if (lambda <= 0.0) {
        return 0.0;
    }

    // Inverse transform method
    return -std::log(U) / lambda;
}

